// Server-only symmetric encryption for OAuth refresh tokens.
//
// Never import this from a 'use client' file — INTEGRATION_ENCRYPTION_KEY would
// be bundled for the browser.
//
// The key is derived by hashing INTEGRATION_ENCRYPTION_KEY to 32 bytes rather
// than requiring exactly-32-raw-bytes-base64, so the env var can be any long
// random string (e.g. one generated by a password manager). Changing the env
// var invalidates every stored ciphertext; the recovery path is to disconnect
// and reconnect the integration.
import { createCipheriv, createDecipheriv, createHash, randomBytes } from 'node:crypto'

const ALGORITHM = 'aes-256-gcm'
const IV_BYTES = 12 // GCM standard nonce length

function key() {
  const secret = process.env.INTEGRATION_ENCRYPTION_KEY
  if (!secret) {
    throw new Error('INTEGRATION_ENCRYPTION_KEY is not set')
  }
  return createHash('sha256').update(secret).digest()
}

/** Seals a secret as `iv:authTag:ciphertext`, each part base64. */
export function encryptSecret(plaintext: string) {
  const iv = randomBytes(IV_BYTES)
  const cipher = createCipheriv(ALGORITHM, key(), iv)
  const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()])
  return [
    iv.toString('base64'),
    cipher.getAuthTag().toString('base64'),
    ciphertext.toString('base64'),
  ].join(':')
}

/** Reverses encryptSecret. Throws if the key changed or the payload was tampered with. */
export function decryptSecret(sealed: string) {
  const [ivPart, tagPart, dataPart] = sealed.split(':')
  if (!ivPart || !tagPart || !dataPart) {
    throw new Error('Malformed encrypted payload')
  }
  const decipher = createDecipheriv(ALGORITHM, key(), Buffer.from(ivPart, 'base64'))
  decipher.setAuthTag(Buffer.from(tagPart, 'base64'))
  return Buffer.concat([
    decipher.update(Buffer.from(dataPart, 'base64')),
    decipher.final(),
  ]).toString('utf8')
}
